<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;700;900&family=Inter:wght@400;500&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --red: #D62828;
      --blue: #1D3557;
      --yellow: #F7C948;
      --black: #000;
      --white: #fff;
      --line: 5px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', sans-serif;
      background: var(--white);
      color: var(--black);
      line-height: 1.6;
      overflow-x: hidden;
    }

    /* ── Hero ─────────────────────────────────────────── */
    .hero {
      position: relative;
      width: 100%;
      height: 100vh;
      min-height: 520px;
      background: var(--white);
      border-bottom: var(--line) solid var(--black);
    }

    #hero-canvas {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      display: block;
    }

    .hero-bar {
      position: absolute;
      bottom: 0; left: 0; right: 0;
      display: grid;
      grid-template-columns: 2fr 1fr;
      border-top: var(--line) solid var(--black);
      background: var(--white);
    }

    .hero-title-cell {
      padding: 1.75rem 2.5rem;
      border-right: var(--line) solid var(--black);
    }

    .hero-title {
      font-family: 'Archivo', sans-serif;
      font-weight: 900;
      font-size: clamp(1.7rem, 4vw, 3.4rem);
      line-height: 1.05;
      text-transform: uppercase;
      letter-spacing: -0.02em;
    }

    .hero-meta-cell {
      padding: 1.75rem 2.5rem;
      display: flex;
      flex-direction: column;
      justify-content: center;
      gap: 0.3rem;
    }

    .hero-meta {
      font-family: 'Archivo', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      text-transform: uppercase;
      letter-spacing: 0.08em;
    }

    .hero-meta span {
      font-weight: 400;
      font-family: 'Inter', sans-serif;
      text-transform: none;
      letter-spacing: 0;
      font-size: 0.88rem;
      opacity: 0.6;
    }

    /* ── Mondrian Grid ────────────────────────────────── */
    .grid {
      display: grid;
      grid-template-columns: 1.2fr 1.8fr;
      grid-template-areas:
        "red work"
        "movement blue"
        "yellow cta";
      border-left: var(--line) solid var(--black);
      border-right: var(--line) solid var(--black);
    }

    .cell {
      padding: 2.5rem;
      border-bottom: var(--line) solid var(--black);
    }

    .cell:last-child { border-bottom: none; }

    .cell--red      { background: var(--red);    color: var(--white); grid-area: red; }
    .cell--work     { grid-area: work; }
    .cell--movement { grid-area: movement; }
    .cell--blue     { background: var(--blue);   color: var(--white); grid-area: blue; }
    .cell--yellow   { background: var(--yellow); color: var(--black); grid-area: yellow; }
    .cell--cta      { grid-area: cta; }

    .label {
      font-family: 'Archivo', sans-serif;
      font-weight: 700;
      font-size: 0.68rem;
      text-transform: uppercase;
      letter-spacing: 0.18em;
      margin-bottom: 1.2rem;
      opacity: 0.55;
    }

    .cell--red .label,
    .cell--blue .label { opacity: 0.75; }

    .cell h2 {
      font-family: 'Archivo', sans-serif;
      font-weight: 900;
      font-size: clamp(1.35rem, 2.4vw, 2.1rem);
      line-height: 1.15;
      text-transform: uppercase;
      margin-bottom: 1rem;
    }

    .cell p {
      font-size: 1rem;
      max-width: 48ch;
    }

    .cell p + p { margin-top: 0.75rem; }

